From 887e6ea9459e17558fd50e1a95423ee31640b8dc Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 28 Nov 2026 13:21:05 +0100
Subject: [PATCH] containmentitem: open the context menu with Shift+F10

Shift+F10, the usual replacement for the Menu key on keyboards without
one, did nothing on the desktop and in panels. Handle it like the Menu
key, so it opens the menu of the focused applet or of the containment.

BUG: 519354
---
 src/plasmaquick/plasmoid/containmentitem.cpp | 5 +++--
 1 file changed, 3 insertions(+), 2 deletions(-)

diff --git a/src/plasmaquick/plasmoid/containmentitem.cpp b/src/plasmaquick/plasmoid/containmentitem.cpp
index d8f65fc21..69eeb7dca 100644
--- a/src/plasmaquick/plasmoid/containmentitem.cpp
+++ b/src/plasmaquick/plasmoid/containmentitem.cpp
@@ -940,14 +940,15 @@ void ContainmentItem::keyPressEvent(QKeyEvent *event)
         return;
     }

-    if (event->key() == Qt::Key_Menu) {
+    const bool shiftF10 = event->keyCombination() == QKeyCombination(Qt::ShiftModifier, Qt::Key_F10);
+    if (event->key() == Qt::Key_Menu || shiftF10) {
         QPointF localPos;
         auto focusedItem = window()->activeFocusItem();
         if (focusedItem) {
             localPos = focusedItem->mapToItem(this, QPointF(0, 0));
         }

-        QMouseEvent me(QEvent::MouseButtonRelease, localPos, QPointF(), Qt::RightButton, Qt::RightButton, event->modifiers());
+        QMouseEvent me(QEvent::MouseButtonRelease, localPos, QPointF(), Qt::RightButton, Qt::RightButton, shiftF10 ? Qt::NoModifier : event->modifiers());
         mousePressEvent(&me);
         event->accept();
     }
-- 
